parameters.command:
=set -euo pipefail; ROOT="${CHELSEA_USER_FILES_ROOT:-/files/chelsea}"; EXPORT_ROOT="${CHELSEA_PRIVACY_EXPORTS_ROOT:-/files/chelsea_privacy_exports}"; TENANT='{{ $json.tenantId }}'; REQUEST='{{ $json.requestId }}'; OP='{{ $json.requestType }}'; case "$TENANT" in tenant_actor_[a-f0-9]*) ;; *) echo '{"success":false,"error":"invalid_tenant"}'; exit 2;; esac; case "$REQUEST" in *[!A-Za-z0-9_.:-]*|'') echo '{"success":false,"error":"invalid_request"}'; exit 2;; esac; TARGET="$ROOT/$TENANT"; OUTDIR="$EXPORT_ROOT/$REQUEST"; [ "${TARGET#"$ROOT/"}" != "$TARGET" ] || exit 3; if [ -L "$TARGET" ]; then echo '{"success":false,"error":"tenant_path_symlink_blocked"}'; exit 4; fi; if [ "$OP" = preview ]; then if [ -d "$TARGET" ]; then COUNT=$(find "$TARGET" -mindepth 1 -print | wc -l); BYTES=$(du -sb "$TARGET" | awk '{print $1}'); else COUNT=0; BYTES=0; fi; printf '{"success":true,"operation":"preview","sourceEntries":%s,"sourceBytes":%s,"mutated":false}
' "$COUNT" "$BYTES"; elif [ "$OP" = export ]; then install -d -m 0700 "$OUTDIR"; OUT="$OUTDIR/files.tar.gz"; if [ -d "$TARGET" ]; then tar -czf "$OUT" -C "$ROOT" "$TENANT"; EXPECTED=$(find "$TARGET" -mindepth 1 -print | wc -l); ACTUAL=$(tar -tzf "$OUT" | tail -n +2 | wc -l); [ "$ACTUAL" -ge "$EXPECTED" ] || { echo '{"success":false,"error":"archive_content_incomplete"}'; exit 6; }; else tar -czf "$OUT" --files-from /dev/null; EXPECTED=0; ACTUAL=0; fi; chmod 0600 "$OUT"; SHA=$(sha256sum "$OUT"|awk '{print $1}'); BYTES=$(stat -c %s "$OUT"); printf '{"success":true,"operation":"export","archivePath":"%s","sha256":"%s","bytes":%s,"sourceEntries":%s,"archiveEntries":%s}
' "$OUT" "$SHA" "$BYTES" "$EXPECTED" "$ACTUAL"; elif [ "$OP" = delete ]; then if [ -e "$TARGET" ]; then rm -rf --one-file-system "$TARGET"; fi; if [ -e "$TARGET" ]; then echo '{"success":false,"error":"delete_readback_failed"}'; exit 5; fi; printf '{"success":true,"operation":"delete","verifiedAbsent":true}
'; else exit 7; fi
